//! Icons the window draws: Lucide's (the React app's lucide-react), as
//! Rune icons on Lucide's 24-point grid. `rune::icon(&icons::HOME, 16.0)`.
//! Add one by pasting its SVG body into [`lucide!`].

use rune::Icon;

macro_rules! lucide {
    ($name:ident, $id:literal, $body:literal) => {
        pub static $name: Icon = Icon {
            name: concat!("lucide-", $id),
            view: 24.0,
            body: concat!(
                r#"<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">"#,
                $body,
                "</g>"
            ),
        };
    };
}

